#include "fstr/automatic_scene_cache.hpp"
#include <atomic>
#include <chrono>
#include <filesystem>
#include <future>
#include <iostream>
#include <stdexcept>
using namespace fstr;
using namespace std::chrono_literals;
namespace {
void check(bool v,const char*s){if(!v)throw std::runtime_error(s);}
std::shared_ptr<const SceneAnalysis> analysis(const AnalysisImage&i){auto v=std::make_shared<SceneAnalysis>();v->width=i.width;v->height=i.height;v->scene.resize(std::size_t(i.width)*std::size_t(i.height));return v;}
struct Release {std::promise<void> promise;std::shared_future<void> ready=promise.get_future().share();bool open=false;void signal(){if(!open){open=true;promise.set_value();}}~Release(){signal();}};
AnalysisImage image(int v){return {2,1,{std::uint8_t(v),20,30,255,40,50,60,255}};}
}
int main(){auto root=std::filesystem::temp_directory_path()/("fstr-cache-latency-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));
struct Cleanup{std::filesystem::path p;~Cleanup(){std::error_code e;std::filesystem::remove_all(p,e);}} cleanup{root};
try{const std::string policy(64,'e');
 // A resident hit must finish while an unrelated backend is still blocked.
 {std::atomic<int> calls{0};Release release;std::promise<void> entered;AutomaticSceneCache cache((root/"resident").string(),policy,[&](const auto&i,double,const auto&){++calls;if(i.rgba[0]==2){entered.set_value();release.ready.wait();}return analysis(i);});auto a=cache.get(image(1),100);
 auto owner=std::async(std::launch::async,[&]{return cache.get(image(2),100);});auto entered_status=entered.get_future().wait_for(2s);if(entered_status!=std::future_status::ready)release.signal();check(entered_status==std::future_status::ready,"Owner did not enter");
 auto hit=std::async(std::launch::async,[&]{return cache.get(image(1),100);});const auto status=hit.wait_for(2s);release.signal();owner.get();auto value=hit.get();check(status==std::future_status::ready&&value==a&&calls==2,"Resident hit waited behind unrelated computation");}
 // Clear returns while a miss is blocked and forbids its old RAM publication.
 {Release release;std::promise<void> entered;AutomaticSceneCache cache((root/"clear").string(),policy,[&](const auto&i,double,const auto&){entered.set_value();release.ready.wait();return analysis(i);});auto owner=std::async(std::launch::async,[&]{return cache.get(image(3),100);});auto status=entered.get_future().wait_for(2s);if(status!=std::future_status::ready)release.signal();check(status==std::future_status::ready,"Clear owner did not enter");
 auto cleared=std::async(std::launch::async,[&]{cache.clear_memory();});auto clear_status=cleared.wait_for(2s);release.signal();cleared.get();auto old=owner.get();auto disk=cache.get(image(3),100);check(clear_status==std::future_status::ready&&old!=disk,"Clear waited or old generation republished");}
 // Queued requests also retain their pre-clear generation after taking miss.
 {Release release;std::promise<void> entered,waiting;AutomaticSceneCache cache((root/"queued-clear").string(),policy,[&](const auto&i,double,const auto&){if(i.rgba[0]==18){entered.set_value();release.ready.wait();}return analysis(i);});auto owner=std::async(std::launch::async,[&]{return cache.get(image(18),100);});auto entered_status=entered.get_future().wait_for(2s);if(entered_status!=std::future_status::ready)release.signal();check(entered_status==std::future_status::ready,"Queued-clear owner did not enter");auto queued=std::async(std::launch::async,[&]{int polls=0;return cache.get(image(19),100,[&]{if(++polls==2)waiting.set_value();});});auto waiting_status=waiting.get_future().wait_for(2s);auto clear=std::async(std::launch::async,[&]{cache.clear_memory();});auto clear_status=clear.wait_for(2s);release.signal();clear.get();auto a=owner.get(),b=queued.get();check(waiting_status==std::future_status::ready&&clear_status==std::future_status::ready,"Queued-clear interleaving not established");check(cache.get(image(18),100)!=a&&cache.get(image(19),100)!=b,"Pre-clear queued request republished into new generation");}
 // Waiting cancellation can call clear_memory: no resident lock surrounds it.
 {Release release;std::promise<void> entered;AutomaticSceneCache cache((root/"wait-cancel").string(),policy,[&](const auto&i,double,const auto&){entered.set_value();release.ready.wait();return analysis(i);});auto owner=std::async(std::launch::async,[&]{return cache.get(image(4),100);});auto status=entered.get_future().wait_for(2s);if(status!=std::future_status::ready)release.signal();check(status==std::future_status::ready,"Cancel owner did not enter");
 auto waiter=std::async(std::launch::async,[&]{try{int polls=0;cache.get(image(5),100,[&]{if(++polls<2)return;cache.clear_memory();throw std::runtime_error("waiter cancelled");});return false;}catch(const std::runtime_error&){return true;}});auto cancelled=waiter.wait_for(2s);release.signal();owner.get();check(waiter.get()&&cancelled==std::future_status::ready,"Cancellation callback was blocked by resident lock");}
 // A second cold key still waits; shared backend concurrency is not expanded.
 {Release release;std::promise<void> entered,waiting;std::atomic<int> active{0},peak{0};AutomaticSceneCache cache((root/"serialize").string(),policy,[&](const auto&i,double,const auto&){int count=++active;int previous=peak.load();while(count>previous&&!peak.compare_exchange_weak(previous,count)){}if(i.rgba[0]==16){entered.set_value();release.ready.wait();}auto result=analysis(i);--active;return result;});auto owner=std::async(std::launch::async,[&]{return cache.get(image(16),100);});auto status=entered.get_future().wait_for(2s);if(status!=std::future_status::ready)release.signal();check(status==std::future_status::ready,"Serial owner did not enter");auto second=std::async(std::launch::async,[&]{int polls=0;return cache.get(image(17),100,[&]{if(++polls==2)waiting.set_value();});});auto waiting_status=waiting.get_future().wait_for(2s);auto second_status=second.wait_for(20ms);release.signal();owner.get();second.get();check(waiting_status==std::future_status::ready&&second_status==std::future_status::timeout&&peak==1,"Different misses ran concurrently");}
 // Failed/cancelled owners release the gate; a same-key waiter can retry.
 for(bool cancel_owner:{false,true}){Release release;std::promise<void> entered;std::atomic<int> calls{0};std::atomic<bool> cancelled{false};AutomaticSceneCache cache((root/(cancel_owner?"owner-cancel":"owner-error")).string(),policy,[&](const auto&i,double,const auto&abort){if(++calls==1){entered.set_value();release.ready.wait();if(cancel_owner)abort();throw std::runtime_error("owner failed");}return analysis(i);});
 auto owner=std::async(std::launch::async,[&]{try{cache.get(image(6),100,[&]{if(cancelled.load())throw std::runtime_error("owner cancelled");});return false;}catch(const std::runtime_error&){return true;}});auto status=entered.get_future().wait_for(2s);if(status!=std::future_status::ready)release.signal();check(status==std::future_status::ready,"Failing owner did not enter");auto waiter=std::async(std::launch::async,[&]{return cache.get(image(6),100);});cancelled=true;release.signal();check(owner.get()&&waiter.get()!=nullptr&&calls==2,"Failed owner stranded waiter or cached failure");}
 // Resident reentry is allowed; recursive misses reject before taking the gate.
 {AutomaticSceneCache* handle=nullptr;AutomaticSceneCache cache((root/"reentry").string(),policy,[&](const auto&i,double,const auto&){if(i.rgba[0]==8){check(handle->get(image(7),100)!=nullptr,"Recursive resident missing");handle->get(image(9),100);}return analysis(i);});handle=&cache;cache.get(image(7),100);bool rejected=false;try{cache.get(image(8),100);}catch(const std::logic_error&){rejected=true;}check(rejected,"Recursive miss did not reject");check(cache.get(image(9),100)!=nullptr,"Reentry error left gate locked");}
 // One complete five-frame window stays resident under the existing byte cap.
 {int calls=0;AutomaticSceneCache cache((root/"window").string(),policy,[&](const auto&i,double,const auto&){++calls;return analysis(i);});std::vector<std::shared_ptr<const SceneAnalysis>> first;for(int i=10;i<15;++i)first.push_back(cache.get(image(i),100));for(int i=10;i<15;++i)check(cache.get(image(i),100)==first[std::size_t(i-10)],"Five-frame window fell back to disk");check(calls==5,"Window repeated inference");}
 std::cout<<"PASS resident independence, clear generation, callback cancellation, owner retry, reentry and five-frame RAM window\n";return 0;
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
